files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --focus: #ffd369;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 30%, #2a2a4a 0%, transparent 50%),
                    radial-gradient(circle at 80% 70%, #1e1e3a 0%, transparent 50%);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 24px;
}

.card {
  background: var(--card);
  border-radius: 20px;
  padding: 32px 28px;
  max-width: 720px;
  width: 100%;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.subtitle {
  color: var(--muted);
  font-size: 1rem;
  margin-bottom: 28px;
}

.swatches {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
  margin-bottom: 28px;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.color-box {
  width: 100%;
  aspect-ratio: 1 / 1.4;
  border-radius: 12px;
  border: 2px solid rgba(255, 255, 255, 0.1);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.hex {
  font-family: ui-monospace, 'SF Mono', Menlo, monospace;
  font-size: 0.8rem;
  color: var(--muted);
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.lock-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 40px;
  padding: 8px 4px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--muted);
  font-size: 0.85rem;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}

.lock-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text);
  border-color: rgba(255, 255, 255, 0.3);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.96);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.lock-btn[aria-pressed="true"]:hover {
  background: #f05a72;
}

.generate-btn {
  display: block;
  width: 100%;
  min-height: 52px;
  padding: 14px 24px;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
  font-size: 1.05rem;
  font-weight: 600;
  font-family: inherit;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.generate-btn:hover {
  background: #f05a72;
  box-shadow: 0 6px 20px rgba(233, 69, 96, 0.35);
}

.generate-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.generate-btn:active {
  transform: scale(0.98);
}

@media (max-width: 560px) {
  body {
    padding: 16px;
  }

  .card {
    padding: 24px 18px;
  }

  .swatches {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }

  .swatch:last-child {
    grid-column: span 2;
  }

  .swatch:last-child .color-box {
    aspect-ratio: 3 / 1;
  }

  h1 {
    font-size: 1.4rem;
  }
}

@media (max-width: 400px) {
  .swatches {
    grid-template-columns: 1fr;
  }

  .swatch:last-child {
    grid-column: auto;
  }

  .swatch:last-child .color-box {
    aspect-ratio: 1 / 0.7;
  }

  .color-box {
    aspect-ratio: 1 / 0.7;
  }
}

(function () {
  'use strict';

  var swatchesEl = document.getElementById('swatches');
  var generateBtn = document.getElementById('generate');
  var swatchCount = 5;
  var locked = new Array(swatchCount).fill(false);
  var colors = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var k = function (n) { return (n + h / 30) % 12; };
    var a = s * Math.min(l, 1 - l);
    var f = function (n) {
      var color = l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return '#' + f(0) + f(8) + f(4);
  }

  function generatePalette() {
    var baseHue = Math.floor(Math.random() * 360);
    var scheme = Math.floor(Math.random() * 3);
    var offsets;

    if (scheme === 0) {
      offsets = [0, 30, 60, 180, 210];
    } else if (scheme === 1) {
      offsets = [0, 72, 144, 216, 288];
    } else {
      offsets = [0, 15, 30, 45, 60];
    }

    var newColors = [];
    for (var i = 0; i < swatchCount; i++) {
      if (locked[i] && colors[i]) {
        newColors.push(colors[i]);
      } else {
        var hue = (baseHue + offsets[i]) % 360;
        var sat = 55 + Math.floor(Math.random() * 30);
        var light = 40 + Math.floor(Math.random() * 25);
        newColors.push(hslToHex(hue, sat, light));
      }
    }
    colors = newColors;
  }

  function render() {
    swatchesEl.innerHTML = '';
    for (var i = 0; i < swatchCount; i++) {
      (function (index) {
        var swatch = document.createElement('div');
        swatch.className = 'swatch';

        var box = document.createElement('div');
        box.className = 'color-box';
        box.style.backgroundColor = colors[index];
        box.setAttribute('aria-hidden', 'true');

        var hex = document.createElement('span');
        hex.className = 'hex';
        hex.textContent = colors[index];

        var lockBtn = document.createElement('button');
        lockBtn.type = 'button';
        lockBtn.className = 'lock-btn';
        lockBtn.setAttribute('aria-pressed', String(locked[index]));
        lockBtn.setAttribute('aria-label',
          (locked[index] ? 'Unlock' : 'Lock') + ' color ' + colors[index]);
        lockBtn.textContent = locked[index] ? '\uD83D\uDD12 Locked' : '\uD83D\uDD13 Lock';

        lockBtn.addEventListener('click', function () {
          locked[index] = !locked[index];
          render();
        });

        swatch.appendChild(box);
        swatch.appendChild(hex);
        swatch.appendChild(lockBtn);
        swatchesEl.appendChild(swatch);
      })(i);
    }
  }

  generateBtn.addEventListener('click', function () {
    generatePalette();
    render();
  });

  generatePalette();
  render();
})();
